const users = [
  { name: 'Alice', age: 30, active: true,  role: 'admin' },
  { name: 'Bob',   age: 17, active: true,  role: 'user'  },
  { name: 'Carol', age: 25, active: false, role: 'user'  },
  { name: 'Dave',  age: 22, active: true,  role: 'user'  }
];

// ── 1. IMPERATIVE: explicit loop, manual accumulation ────────────
function getActiveAdultsImperative(users) {
  const result = [];
  for (let i = 0; i < users.length; i++) {
    if (users[i].active && users[i].age >= 18) {
      result.push(users[i].name.toUpperCase());
    }
  }
  return result;
}
console.log('Imperative:', getActiveAdultsImperative(users));
// ['ALICE', 'DAVE']

// ── 2. OOP: encapsulated collection with chainable methods ───────
class UserCollection {
  #users;
  constructor(users) { this.#users = [...users]; }  // defensive copy

  filterActive() { return new UserCollection(this.#users.filter(u => u.active)); }
  filterAdults() { return new UserCollection(this.#users.filter(u => u.age >= 18)); }
  mapNames()     { return this.#users.map(u => u.name.toUpperCase()); }
  count()        { return this.#users.length; }
}
const collection = new UserCollection(users);
console.log('OOP:', collection.filterActive().filterAdults().mapNames());
// ['ALICE', 'DAVE']
console.log('OOP count:', collection.filterActive().count()); // 3

// ── 3. FUNCTIONAL: pure predicates, HOFs, composition ───────────
const isActive    = u => u.active;
const isAdult     = u => u.age >= 18;
const toUpperName = u => u.name.toUpperCase();

// Compose two predicates into one using a higher-order function
const both   = (f, g) => x => f(x) && g(x);
const either = (f, g) => x => f(x) || g(x);

const activeAdult = both(isActive, isAdult);

const result = users.filter(activeAdult).map(toUpperName);
console.log('Functional:', result);
// ['ALICE', 'DAVE']

// pipe: left-to-right function composition
const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);
const process = pipe(
  users => users.filter(isActive),
  users => users.filter(isAdult),
  users => users.map(toUpperName)
);
console.log('Pipe:', process(users));
// ['ALICE', 'DAVE']

// ── 4. DECLARATIVE: describe WHAT, not HOW ──────────────────────
const query = {
  where: [isActive, isAdult],
  select: toUpperName
};
const runQuery = ({ where, select }, data) =>
  where.reduce((acc, pred) => acc.filter(pred), data).map(select);
console.log('Declarative:', runQuery(query, users));
// ['ALICE', 'DAVE']

// ── Pure vs Impure — the distinction in code ──────────────────

// PURE: deterministic, no side effects
const add = (a, b) => a + b;                      // pure
const square = x => x * x;                        // pure
const fullName = user => `${user.first} ${user.last}`; // pure
const applyDiscount = (price, pct) => price * (1 - pct / 100); // pure

// IMPURE: reads external state or causes side effects
let taxRate = 0.08;
const withTax = price => price * (1 + taxRate);   // impure: reads external mutable
const log = msg => { console.log(msg); return msg; }; // impure: I/O side effect
const now = () => Date.now();                     // impure: non-deterministic

// ── Immutability patterns in JS ──────────────────────────────
const user = { name: 'Alice', score: 10, tags: ['admin'] };

// MUTABLE (imperative style) — modifies in place
const mutableUpdate = u => { u.score += 5; return u; };

// IMMUTABLE (functional style) — returns new object, original unchanged
const givePoints = (u, pts) => ({ ...u, score: u.score + pts });
const addTag     = (u, tag) => ({ ...u, tags: [...u.tags, tag] });

const updated = givePoints(user, 5);
const tagged  = addTag(updated, 'vip');
console.log(user.score);    // 10 — original unchanged
console.log(updated.score); // 15
console.log(tagged.tags);   // ['admin', 'vip']

// ── Higher-order functions: building an abstraction toolkit ──
const map    = f => arr => arr.map(f);            // curried map
const filter = p => arr => arr.filter(p);         // curried filter
const reduce = (f, init) => arr => arr.reduce(f, init);

const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);
const compose = (...fns) => x => fns.reduceRight((v, f) => f(v), x);

// Build a reusable processing pipeline from small pieces
const sumActiveScores = pipe(
  filter(u => u.active),
  map(u => u.score),
  reduce((acc, s) => acc + s, 0)
);

const team = [
  { name: 'A', active: true,  score: 10 },
  { name: 'B', active: false, score: 99 },
  { name: 'C', active: true,  score: 25 }
];
console.log(sumActiveScores(team)); // 35

// ── Closures as encapsulated state (FP-style) ────────────────
const makeCounter = (start = 0, step = 1) => {
  let current = start;             // captured in closure
  return {
    next:  () => (current += step),
    reset: () => (current = start),
    value: () => current
  };
};
const c = makeCounter(0, 2);
console.log(c.next(), c.next(), c.next()); // 2 4 6
c.reset();
console.log(c.value()); // 0

// ── Multi-paradigm: a shopping cart that mixes all styles ─────

// OOP: Cart manages state + business rules (encapsulation)
class Cart {
  #items = [];
  #discountCode = null;

  addItem(item)  { this.#items = [...this.#items, item]; return this; } // immutable update
  setDiscount(code) { this.#discountCode = code; return this; }

  // FP: pure function for total calculation (no side effects)
  #calcSubtotal() {
    return this.#items.reduce((sum, item) => sum + item.price * item.qty, 0);
  }

  // FP: pure discount application
  #applyDiscount(subtotal) {
    const discounts = { SAVE10: 0.10, SAVE20: 0.20, VIP: 0.30 };
    const rate = discounts[this.#discountCode] ?? 0;
    return subtotal * (1 - rate);
  }

  // Imperative: explicit conditional logic
  checkout(taxRate = 0.08) {
    const subtotal = this.#calcSubtotal();
    const afterDiscount = this.#applyDiscount(subtotal);
    const tax = afterDiscount * taxRate;
    const total = afterDiscount + tax;
    // Imperative: mutate the checkout result object
    return { subtotal, discount: subtotal - afterDiscount, tax, total };
  }

  // Declarative: describe summary structure
  summary() {
    return this.#items.map(({ name, price, qty }) => ({
      name,
      lineTotal: (price * qty).toFixed(2)
    }));
  }
}

const cart = new Cart();
cart
  .addItem({ name: 'Book',   price: 29.99, qty: 2 })
  .addItem({ name: 'Pen',    price:  4.99, qty: 5 })
  .addItem({ name: 'Tablet', price: 299.00, qty: 1 })
  .setDiscount('SAVE10');

console.log('Summary:', cart.summary());
console.log('Checkout:', cart.checkout());
// { subtotal: 384.93, discount: 38.49, tax: 31.07, total: 377.51 }

// ── Standalone FP utilities (pure, reusable across any context) ─
const formatCurrency = n => `$${n.toFixed(2)}`;
const sumBy = key => arr => arr.reduce((s, x) => s + x[key], 0);
const withTax = rate => amount => amount * (1 + rate);

const prices = [29.99, 4.99, 299.00];
const total = withTax(0.08)(prices.reduce((s, p) => s + p, 0));
console.log(formatCurrency(total)); // $360.81

// ── Declarative query simulation (like SQL in JS) ─────────────
const inventory = [
  { name: 'Book',   qty: 50, category: 'stationery', price: 29.99 },
  { name: 'Tablet', qty:  5, category: 'electronics', price: 299.00 },
  { name: 'Pen',    qty: 200, category: 'stationery', price: 4.99 },
  { name: 'Laptop', qty:  2, category: 'electronics', price: 999.00 }
];
const select = (fields, data) => data.map(row =>
  Object.fromEntries(fields.map(f => [f, row[f]]))
);
const where = (pred, data) => data.filter(pred);
const orderBy = (key, data) => [...data].sort((a, b) => b[key] - a[key]);

// SELECT name, price FROM inventory WHERE category='electronics' ORDER BY price DESC
const electronicsQuery = orderBy(
  'price',
  select(['name', 'price'], where(p => p.category === 'electronics', inventory))
);
console.log('Electronics:', electronicsQuery);
// [{ name: 'Laptop', price: 999 }, { name: 'Tablet', price: 299 }]
